effect.shader:
void main() {
    if (trailLen <= 0.0) { fragColor = texture(inputImg, acScreenNorm); return; }
    int n = clamp(int(samples), 4, 48);
    float rad = radians(angle);
    vec2 dir = vec2(cos(rad), sin(rad));
    dir.x /= acAspect;

    vec4 soma = vec4(0.0);
    for (int i = 0; i <= 48; i++) {
        if (i > n) break;
        float t = float(i) / float(n) - 0.5;
        soma += texture(inputImg, acScreenNorm + dir * trailLen * t);
    }
    fragColor = soma / float(n + 1);
}
